/*
 * msvcrt load-fixing proxy (dxmsvc.dll): everything but the one entry below is a loader
 * forwarder in msvcrt.def, generated by tools/gen_msvcrt_def.py.
 */

/* _libm_sse2_sqrt_precise takes its operand and returns its result in xmm0, which on
 * x86 is not where a C double goes, so it is written out there.  Elsewhere a double
 * argument and result already live in xmm0 (or d0), and only x86 binaries import it. */
#if defined(__i386__)
__asm__(".text\n"
        ".globl _dxcts_libm_sse2_sqrt_precise\n"
        "_dxcts_libm_sse2_sqrt_precise:\n\t"
        "sqrtsd %xmm0, %xmm0\n\t"
        "ret\n");
#else
double dxcts_libm_sse2_sqrt_precise(double x)
{
    return __builtin_sqrt(x);
}
#endif
